import { useState } from 'react';
import { CoachCelo } from './CoachCelo';
export function OptionLab(){
 const [kind,setKind]=useState<'call'|'put'>('call'),[strike,setStrike]=useState(100),[premium,setPremium]=useState(3),[stock,setStock]=useState(103),[quantity,setQuantity]=useState(1);
 const intrinsic=(price:number)=>Math.max(0,kind==='call'?price-strike:strike-price);
 const profit=(price:number)=>(intrinsic(price)-premium)*100*quantity;
 const result=profit(stock),breakeven=kind==='call'?strike+premium:strike-premium;
 const xs=(n:number)=>40+(n-70)/60*520,ys=(n:number)=>210-n/(4500*quantity)*145;
 const path=Array.from({length:61},(_,i)=>`${i?'L':'M'}${xs(70+i)},${ys(profit(70+i))}`).join(' ');
 const money=(n:number)=>n.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:0,maximumFractionDigits:2});
 return <section className="option-lab"><div><p className="portal-eyebrow">INTERACTIVE LAB · INVENTED PRICES</p><h2>Change the trade. See what changes.</h2><p>Explore a purchased option at expiration. Move the stock price first, then change what you paid.</p></div><div className="lab-layout"><div className="lab-controls"><div className="flex gap-2"><button className={`btn ${kind==='call'?'btn-primary':'btn-ghost'}`} onClick={()=>setKind('call')}>Buy a call</button><button className={`btn ${kind==='put'?'btn-primary':'btn-ghost'}`} onClick={()=>setKind('put')}>Buy a put</button></div>{[
 ['Stock price at expiration',stock,setStock,70,130,1,'$'],['Strike price',strike,setStrike,85,115,1,'$'],['Premium paid per share',premium,setPremium,1,10,.5,'$'],['Contracts',quantity,setQuantity,1,5,1,'']
 ].map(([label,value,set,min,max,step,prefix])=><label key={String(label)}><span>{String(label)} <strong>{String(prefix)}{Number(value)}</strong></span><input aria-label={String(label)} type="range" min={Number(min)} max={Number(max)} step={Number(step)} value={Number(value)} onChange={e=>(set as (v:number)=>void)(Number(e.target.value))}/></label>)}<p className="text-sm">One standard contract represents 100 shares. This lab excludes fees and assumes no exercise or stock position.</p></div><div><div className="lab-results"><div><span>You paid</span><strong>{money(premium*100*quantity)}</strong></div><div><span>Option value at expiration</span><strong>{money(intrinsic(stock)*100*quantity)}</strong></div><div data-positive={result>=0}><span>Profit / loss before fees</span><strong>{result>0?'+':''}{money(result)}</strong></div></div><svg viewBox="0 0 600 300" role="img" aria-label={`Expiration profit diagram. Stock ${stock}, profit ${result} dollars before fees.`}><line x1="40" x2="560" y1="210" y2="210" stroke="var(--ink-muted)" strokeDasharray="4 4"/><path d={path} fill="none" stroke="#3159db" strokeWidth="4"/><circle cx={xs(stock)} cy={ys(result)} r="7" fill={result>=0?'#14825f':'#bd3d54'}/><text x="40" y="30" fill="var(--ink-muted)">Profit above the dotted line. Loss below it.</text>{[70,85,100,115,130].map(n=><text key={n} x={xs(n)} y="280" textAnchor="middle" fill="var(--ink-muted)">${n}</text>)}</svg><CoachCelo><p>{result>0?`The option is worth more than you paid. Your gain is ${money(result)} before fees.`:result===0?'You recovered the premium, but fees would still leave a small loss.':`The option has not recovered its cost. Your loss is ${money(-result)} before fees.`} At expiration, this {kind} breaks even at a stock price of {money(breakeven)}, before fees.</p></CoachCelo></div></div><details className="mt-4"><summary>See the calculation and its limits</summary><p className="mt-2">Call value per share = the greater of zero or stock price minus strike. Put value = the greater of zero or strike minus stock price. Profit = (option value minus premium paid) × 100 × contracts. Before expiration, time remaining and market expectations also affect an option’s price. This diagram cannot predict an early sale price.</p></details></section>;
}
